UserEmail.getValidationStatus = async function (uid) {
	const userData = await user.getUserFields(uid, ['email', 'email:confirmed']);
	const code = await db.get(confirmationKey(uid));
	const confirmObj = code ? await db.getObject(`confirm:${code}`) : null;
	if (!userData.email && (!confirmObj || !confirmObj.email)) {
		return '(no email)';
	}
	if (parseInt(userData['email:confirmed'], 10) === 1) {
		return 'Validated';
	}
	if (confirmObj && parseInt(confirmObj.uid, 10) === parseInt(uid, 10) && confirmObj.email) {
		return Number(confirmObj.expires) > Date.now() ? 'Validation Pending' : 'Validation Expired';
	}
	return 'Validation Expired';
};

UserEmail.expireValidation = async function (uid) {
	const key = confirmationKey(uid);
	const code = await db.get(key);
	await db.delete(key);
	if (code) {
		await db.delete(`confirm:${code}`);
	}
};

UserEmail.sendValidationEmail = async function (uid, options) {
	/*
	 * 	Options:
	 * 		- email, overrides email retrieval
	 * 		- force, sends email even if it is too soon to send another
	 * 		- emailChange, indicates an email change rather than a validation resend
	 */

	options = options || {};

	// Fallback behaviour (email passed in as second argument)
	if (typeof options === 'string') {
		options = {
			email: options,
		};
	}

	let confirm_code = utils.generateUUID();

	const emailInterval = meta.config.emailConfirmInterval;
	const currentUser = await user.getUserFields(uid, ['email']);
	const currentEmail = currentUser.email;
	if (options.email && typeof options.email === 'string') {
		options.email = options.email.trim();
	}
	const emailMatchesCurrent = options.email && currentEmail &&
		options.email.toLowerCase() === currentEmail.toLowerCase();
	if (emailMatchesCurrent && options.emailChange) {
		throw new Error('[[error:email-nochange]]');
	}
	if (!options.email || !options.email.length) {
		options.email = await UserEmail.getEmailForValidation(uid);
	}
	if (!options.email) {
		throw new Error('[[error:invalid-email]]');

